package org.apache.tika.sax;

import org.apache.tika.parser.ParseContext;
import org.apache.tika.config.OutputLimits;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;

import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.io.UnsupportedEncodingException;
import java.nio.charset.Charset;
import java.util.Locale;
import org.xml.sax.ContentHandler;
import org.xml.sax.helpers.DefaultHandler;

public class BasicContentHandlerFactory_newInstance_2_0_Test {

    @Test
    public void testNewInstance() throws Exception {
        ParseContext parseContext = mock(ParseContext.class);
        OutputLimits outputLimits = mock(OutputLimits.class);
        when(parseContext.get(OutputLimits.class)).thenReturn(outputLimits);
        when(outputLimits.getWriteLimit()).thenReturn(100);
        when(outputLimits.isThrowOnWriteLimit()).thenReturn(true);

        BasicContentHandlerFactory factory = new BasicContentHandlerFactory();
        BasicContentHandlerFactory result = (BasicContentHandlerFactory) factory.getClass()
                .getMethod("newInstance", HANDLER_TYPE.class, ParseContext.class)
                .invoke(factory, HANDLER_TYPE.MARKDOWN, parseContext);

        assertEquals(HANDLER_TYPE.MARKDOWN, result.getType());
        assertEquals(100, result.getWriteLimit());
        assertEquals(true, result.isThrowOnWriteLimitReached());
        assertEquals(parseContext, result.getParseContext());
    }
}
